   const columns=Array.isArray(c.columns)?c.columns:[{title:'Opportunities',tone:'success',items:['A clear problem with a focused approach.','Strong evidence that supports the next step.']},{title:'Considerations',tone:'danger',items:['An assumption that still needs validation.','A dependency to resolve before moving ahead.']}];
